import Foundation

public enum PasteboardFilter {
    public static let ownMarkerType = "com.maicolsantos.clips.internal"

    public static let sensitiveTypes: Set<String> = [
        ownMarkerType,
        "org.nspasteboard.TransientType",
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.agilebits.onepassword.concealed",
        "com.bitwarden.pasteboard.concealed",
        "net.keepassxc.keepassxc",
        "de.keepassx.keepassx",
        "com.lastpass.LastPass",
        "com.strongbox.mac.concealed",
        "com.apple.security.pboard.concealed"
    ]

    public static func shouldIgnore(types: [String]) -> Bool {
        for type in types {
            if sensitiveTypes.contains(type) {
                return true
            }
            let lower = type.lowercased()
            if lower.contains("concealed")
                || lower.contains("transient")
                || lower.contains("autogenerated")
                || lower.contains("onepassword")
                || lower.contains("bitwarden")
                || lower.contains("keepass")
                || lower.contains("lastpass")
                || lower.contains("strongbox") {
                return true
            }
        }
        return false
    }
}
